      env.N8N_CONNECTOR_WEBHOOK_BASE_URL ||
      env.N8N_PUBLIC_WEBHOOK_URL ||
      'http://n8n:5678';
    const normalized = base.replace(/\/$/, '');
    return `${normalized}/webhook/${path}`;
  }
  return env.N8N_TOOL_STEP_WEBHOOK_URL || 'http://n8n:5678/webhook/chat-tool-step';
}

